#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using System.Globalization;
using System.Linq;
using MukioI18n;
using MVZ2.Managers;
using MVZ2.Options;
using MVZ2Logic;
using MVZ2Logic.Games;
using MVZ2Logic.Localization;
using MVZ2Logic.Options;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Localization
{
    public partial class LanguageManager : MonoBehaviour, IGlobalLocalization
    {
        public string _(string? text, params object?[] args)
        {
            return GetLocalizedString(text, GetCurrentLanguage(), args);
        }
        public string _p(string context, string? text, params object?[] args)
        {
            return GetLocalizedStringParticular(context, text, GetCurrentLanguage(), args);
        }
        public string _n(string text, string textPlural, long n, params object?[] args)
        {
            return GetLocalizedStringPlural(text, textPlural, n, GetCurrentLanguage(), args);
        }
        public string _n(string text, long n, params object?[] args)
        {
            return _n(text, text, n, args);
        }
        public string _pn(string context, string text, string textPlural, long n, params object?[] args)
        {
            return GetLocalizedStringParticularPlural(context, text, textPlural, n, GetCurrentLanguage(), args);
        }
        public string _pn(string context, string text, long n, params object?[] args)
        {
            return _pn(context, text, text, n, args);
        }
        public string GetLocalizedString(string? text, string language, params object?[] args)
        {
            if (string.IsNullOrEmpty(text))
                return string.Empty;
            if (TryGetLocalizedString(text, language, out var str, args))
                return str;
            return string.Format(text, args);
        }
        public bool TryGetLocalizedString(string text, string language, [NotNullWhen(true)] out string? translated, params object?[] args)
        {
            foreach (var provider in catalogProviders)
            {
                if (provider.TryGetString(language, text, out var result, args))
                {
                    translated = result;
                    return true;
                }
            }
            translated = null;
            return false;
        }
        public string GetLocalizedStringParticular(string context, string? text, string language, params object?[] args)
        {
            if (string.IsNullOrEmpty(text))
                return string.Empty;
            if (TryGetLocalizedStringParticular(context, text, language, out var str, args))
                return str;
            return string.Format(text, args);
        }
        public bool TryGetLocalizedStringParticular(string context, string text, string language, [NotNullWhen(true)] out string? translated, params object?[] args)
        {
            foreach (var provider in catalogProviders)
            {
                if (provider.TryGetStringParticular(language, context, text, out var result, args))
                {
                    translated = result;
                    return true;
                }
            }
            translated = null;
            return false;
        }
        public string GetLocalizedStringPlural(string text, string textPlural, long n, string language, params object?[] args)
        {
            if (string.IsNullOrEmpty(text))
                return string.Empty;
            if (TryGetLocalizedStringPlural(text, textPlural, n, language, out var str, args))
                return str;
            return string.Format(n > 1 ? text : textPlural, args);
        }
        public bool TryGetLocalizedStringPlural(string text, string textPlural, long n, string language, [NotNullWhen(true)] out string? translated, params object?[] args)
        {
            foreach (var provider in catalogProviders)
            {
                if (provider.TryGetStringPlural(language, text, textPlural, n, out var result, args))
                {
                    translated = result;
                    return true;
                }
            }
            translated = null;
            return false;
        }
        public string GetLocalizedStringParticularPlural(string context, string text, string textPlural, long n, string language, params object?[] args)
        {
            if (string.IsNullOrEmpty(text))
                return string.Empty;
            if (TryGetLocalizedStringParticularPlural(context, text, textPlural, n, language, out var str, args))
                return str;
            return string.Format(n > 1 ? text : textPlural, args);
        }
        public bool TryGetLocalizedStringParticularPlural(string context, string text, string textPlural, long n, string language, [NotNullWhen(true)] out string? translated, params object?[] args)
        {
            foreach (var provider in catalogProviders)
            {
                if (provider.TryGetStringParticularPlural(language, context, text, textPlural, n, out var result, args))
                {
                    translated = result;
                    return true;
                }
            }
            translated = null;
            return false;
        }

        public void CallLanguageChanged(string lang)
        {
            OnLanguageChanged?.Invoke(lang);
        }

        #region Provider
        public void AddCatalogProvider(ICatalogProvider provider)
        {
            catalogProviders.Add(provider);
        }
        public bool RemoveCatalogProvider(ICatalogProvider provider)
        {
            return catalogProviders.Remove(provider);
        }
        #endregion

        #region 语言代码
        public string GetLanguageName(string language)
        {
            try
            {
                if (TryGetLocalizedStringParticular(LogicStrings.CONTEXT_LANGUAGE_NAME, CURRENT_LANGUAGE_NAME, language, out var name))
                {
                    return name;
                }
                var cultureInfo = CultureInfo.GetCultureInfo(language);
                return $"{cultureInfo.NativeName}({language})";
            }
            catch (CultureNotFoundException)
            {
                return language;
            }
        }
        public string GetCurrentLanguage()
        {
            return currentLanguage;
        }
        public string[] GetAllLanguageCodes()
        {
            return allLanguages.ToArray();
        }
        public void ReevaluateLanguages()
        {
            allLanguages.Clear();
            allLanguages.Add(SOURCE_LANGUAGE);
            foreach (var provider in catalogProviders)
            {
                var codes = provider.GetAllLanguageCodes();
                foreach (var code in codes)
                {
                    if (!allLanguages.Contains(code))
                    {
                        allLanguages.Add(code);
                    }
                }
            }
            if (!allLanguages.Contains(GetCurrentLanguage()))
            {
                Main.OptionsManager.SetLanguage(allLanguages.FirstOrDefault());
            }
        }
        #endregion
        private void Awake()
        {
            OptionsManager.OnOptionChangedString += OnOptionChangedStringCallback;
        }
        private void OnOptionChangedStringCallback(NamespaceID id, string value)
        {
            if (id == LogicOptionItemID.language)
            {
                if (string.IsNullOrEmpty(value))
                {
                    value = GetEnvironmentLanguage();
                }
                currentLanguage = value;
                Main.LanguageManager.CallLanguageChanged(value);
            }
        }
        private static string GetEnvironmentLanguage()
        {
            var culture = CultureInfo.CurrentCulture;
            var allLanguages = Global.Localization.GetAllLanguageCodes();
            foreach (var language in allLanguages)
            {
                if (culture.Name == language)
                    return language;
                var langCulture = new CultureInfo(language);
                if (culture.Parent == langCulture.Parent)
                    return language;
            }
            return CN;
        }
        string IGlobalLocalization.GetText(string textKey, params object[] args)
        {
            return _(textKey, args);
        }
        string IGlobalLocalization.GetTextParticular(string textKey, string context, params object[] args)
        {
            return _p(context, textKey, args);
        }
        string IGlobalLocalization.GetTextPlural(string textKey, string textPlural, long n, params object[] args)
        {
            return _n(textKey, textPlural, n, args);
        }
        string IGlobalLocalization.GetTextPluralParticular(string textKey, string textPlural, long n, string context, params object[] args)
        {
            return _pn(context, textKey, textPlural, n, args);
        }
        public event Action<string>? OnLanguageChanged;
        public MainManager Main => main;
        public const string CN = "zh-Hans";
        public const string EN = "en-US";
        public const string SOURCE_LANGUAGE = CN;

        [TranslateMsg("当前语言名称", LogicStrings.CONTEXT_LANGUAGE_NAME)]
        public const string CURRENT_LANGUAGE_NAME = "中文";

        private readonly List<string> allLanguages = new List<string>() { SOURCE_LANGUAGE };
        private readonly List<ICatalogProvider> catalogProviders = new List<ICatalogProvider>();
        private string currentLanguage = CN;
        [SerializeField]
        private MainManager main = null!;
    }
}
